104	        audit.recordOnCommit(record("CLAIM_ADDED", user, person, saved));
105	        if (saved.isLateEntry()) {
106	            audit.recordOnCommit(record("LATE_ENTRY", user, person, saved));
107	        }
108	        rollup.recordChanges(sheetId, user, before);
