112	    @Transactional
113	    public Claim update(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
114	            String corrects) {
115	        RollupService.Snapshot before = rollup.snapshot(sheetId);
116	        Claim claim = claims.findForUpdate(id, sheetId)
117	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
118	        // Only a DRAFT can be edited: an OPEN claim is changed by voiding it and adding a new one.
119	        if (claim.getStatus() != ClaimStatus.DRAFT) {
120	            throw new ClaimNotEditableException(id, claim.getStatus());
121	        }
122	        // Not while another user has its editor open.
123	        if (claim.isLockedAgainst(user)) {
124	            throw new ClaimLockedException(id, claim.getLockedBy());
125	        }
126	        LocalDate dated = dateOr(sheetId, date);
127	        // Neither out of nor into a closed period.
128	        periods.requireOpen(sheetId, claim.getDate(), dated);
129	        people.findByIdAndSheetId(claim.getPersonId(), sheetId)
130	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()))
131	                .requireClaimable(dated);
132	        LocalDate correctedDate = requireCorrection(sheetId, claim.getPersonId(), amount, corrects);
133	        claim.setAmount(amount);
134	        claim.setCorrects(corrects);
135	        claim.setDate(dated);
136	        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
137	        claim.setNote(noteOf(note));
138	        // Saving the editor releases its lock.
139	        claim.setLockedBy(null);
140	        Claim saved = claims.saveAndFlush(claim);
141	        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
142	                .orElseThrow(() -> new PersonNotFoundException(sheetId, saved.getPersonId()));
143	        audit.recordOnCommit(record("CLAIM_EDITED", user, person, saved));
144	        rollup.recordChanges(sheetId, user, before);
145	        return saved;
146	    }
