148	    /**
149	     * Open the claim's editor for the user, locking the claim against other users' edits until it is saved or
150	     * cancelled, or the sheet's today changes. Refused, taking no lock, for a claim that cannot be edited: not a DRAFT,
151	     * dated in a closed period, or locked by another user. The user's own lock is taken again.
152	     */
153	    @Transactional
154	    public Claim lock(String sheetId, String user, Long id) {
155	        Claim claim = claims.findForUpdate(id, sheetId)
156	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
157	        if (claim.getStatus() != ClaimStatus.DRAFT) {
158	            throw new ClaimNotEditableException(id, claim.getStatus());
159	        }
160	        periods.requireOpen(sheetId, claim.getDate());
161	        if (claim.isLockedAgainst(user)) {
162	            throw new ClaimLockedException(id, claim.getLockedBy());
163	        }
164	        claim.setLockedBy(user);
165	        return claims.saveAndFlush(claim);
