180	    /**
181	     * Move a claim to another status, if its current one allows it; refused otherwise. A clerk settling a claim whose
182	     * due is above the clerk limit sends it to PENDING instead, for a steward to approve or reject.
183	     */
184	    @Transactional
185	    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus status) {
186	        Claim claim = claims.findForUpdate(id, sheetId)
187	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
188	        boolean voidsSettled = status == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
189	        if (!voidsSettled && (!claim.getStatus().canMoveTo(status) || status == ClaimStatus.PENDING)) {
190	            throw new ClaimStatusException(id, claim.getStatus(), status);
191	        }
192	        // The sheet's permission matrix decides which roles may open, settle or void.
193	        String action = switch (status) {
194	            case OPEN -> "open";
195	            case SETTLED -> "settle";
196	            case VOID -> "void";
197	            case DRAFT, PENDING -> throw new ClaimStatusException(id, claim.getStatus(), status);
198	        };
199	        if (!roles.may(sheetId, user, action)) {
200	            throw new ClaimActionForbiddenException(id, user, action);
201	        }
202	        if (voidsSettled) {
203	            requireSettledVoidable(sheetId, user, claim);
204	        }
205	        periods.requireOpen(sheetId, claim.getDate());
206	        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
207	        if (status == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
208	            throw new ClaimDeferException(id, "it is deferred until " + claim.getDeferredUntil());
209	        }
210	        // Four eyes: whoever opened a claim cannot also settle it.
211	        if (status == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
212	            throw new ClaimSettledByOpenerException(id, user);
213	        }
214	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
215	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
216	        if (status == ClaimStatus.SETTLED) {
217	            requireProof(sheetId, person, claim);
218	        }
219	        if (status == ClaimStatus.OPEN) {
220	            requireNote(sheetId, person, claim);
221	        }
222	        // A clerk settles only a claim whose due (the one its statement bound it to, else worked out from the rate)
223	        // is at or below the clerk limit; one above it goes to PENDING. A due of n/a is within any limit.
224	        if (status == ClaimStatus.SETTLED && roles.roleOf(sheetId, user) == Role.CLERK) {
225	            BigDecimal limit = settings.get(sheetId).getClerkLimit();
226	            BigDecimal due = liveDue(sheetId, claim, figureOf(sheetId, person, claim));
227	            if (limit != null && due != null && due.compareTo(limit) > 0) {
228	                status = ClaimStatus.PENDING;
229	            }
230	        }
231	        RollupService.Snapshot before = rollup.snapshot(sheetId);
232	        String due = status == ClaimStatus.SETTLED ? settle(sheetId, person, claim)
233	                : voidsSettled ? " reversed=" + shownDue(sheetId, person, claim) : "";
234	        claim.setStatus(status);
235	        // A voided claim keeps its number (never reused), and the CLAIM_VOIDED record carries it.
236	        String number = claim.getNumber();
237	        if (status == ClaimStatus.OPEN) {
238	            number = nextNumber(sheetId, claim.getDate());
239	            claim.setNumber(number);
240	            claim.setOpenedBy(user);
241	        }
242	        Claim saved = claims.saveAndFlush(claim);
243	        log(sheetId, user, person, saved);
244	        String event = switch (status) {
245	            case OPEN -> "CLAIM_OPENED";
246	            case PENDING -> "CLAIM_PENDING";
247	            case SETTLED -> "CLAIM_SETTLED";
248	            case VOID -> "CLAIM_VOIDED";
249	            case DRAFT -> throw new IllegalStateException();
250	        };
251	        audit.recordOnCommit(record(event, user, person, saved) + numberOf(number) + due);
252	        if (status == ClaimStatus.SETTLED) {
253	            watches.notifyWatchers(sheetId, user, person, number);
254	        }
255	        rollup.recordChanges(sheetId, user, before);
256	        return saved;
257	    }
