351	        if (until == null || !until.isAfter(today)) {
352	            throw new ClaimDeferException(id, "it can only be deferred to a date after " + today);
353	        }
354	        periods.requireOpen(sheetId, claim.getDate());
355	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
356	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
357	        RollupService.Snapshot before = rollup.snapshot(sheetId);
358	        claim.setDeferredUntil(until);
359	        Claim saved = claims.saveAndFlush(claim);
360	        audit.recordOnCommit(record("CLAIM_DEFERRED", user, person, saved) + numberOf(saved.getNumber())
361	                + " until=" + until);
362	        rollup.recordChanges(sheetId, user, before);
363	        return saved;
