366	    /**
367	     * A steward re-settles a SETTLED claim: its due is frozen again at the figure it would have today as an OPEN claim
368	     * bound by no statement (today's rates and grades with its late charge as of today, raised to the floor). Refused for any other
369	     * status, a closed period, or a user not a steward.
370	     */
371	    @Transactional
372	    public Claim resettle(String sheetId, String user, Long id) {
373	        Claim claim = claims.findForUpdate(id, sheetId)
374	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
375	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
376	            throw new ClaimResettleForbiddenException(id, user);
377	        }
378	        if (claim.getStatus() != ClaimStatus.SETTLED) {
379	            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.SETTLED);
380	        }
381	        periods.requireOpen(sheetId, claim.getDate());
382	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
383	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
384	        RollupService.Snapshot before = rollup.snapshot(sheetId);
385	        String old = shownDue(sheetId, person, claim);
386	        BigDecimal figure = dueOf(sheetId, person, claim);
387	        Sheet sheet = settings.get(sheetId);
388	        claim.setSettledDue(claim.isCorrection() ? figure
389	                : sheet.floored(sheet.withLateCharge(figure, true, claim.getDueBy(), claim.getDate()), claim.getDate()));
390	        Claim saved = claims.saveAndFlush(claim);
391	        log(sheetId, user, person, saved);
392	        audit.recordOnCommit(record("CLAIM_RESETTLED", user, person, saved) + numberOf(saved.getNumber())
393	                + " old=" + old + " new=" + shownDue(sheetId, person, saved));
394	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
395	        rollup.recordChanges(sheetId, user, before);
396	        return saved;
397	    }
