399	    /**
400	     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure its statement bound it
401	     * to stays bound; its period follows the new date, and while the sheet numbers by period a claim moved into another
402	     * period takes the next number of that period's sequence (its old one is never used again). Refused for any other
403	     * status, a date after its person's retirement, a claim in a closed period or a new date in one, or a user not a
404	     * steward.
405	     */
406	    @Transactional
407	    public Claim redate(String sheetId, String user, Long id, LocalDate date) {
408	        Claim claim = claims.findForUpdate(id, sheetId)
409	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
410	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
411	            throw new ClaimRedateForbiddenException(id, user);
412	        }
413	        if (!claim.getStatus().isOpen()) {
414	            throw new ClaimRedateException(id, "it is " + claim.getStatus()
415	                    + ", only an OPEN or PENDING claim can be re-dated");
416	        }
417	        LocalDate old = claim.getDate();
418	        // Neither out of nor into a closed period.
419	        periods.requireOpen(sheetId, old, date);
420	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
421	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
422	        person.requireClaimable(date);
423	        RollupService.Snapshot before = rollup.snapshot(sheetId);
424	        if (settings.get(sheetId).numbersByPeriod()
425	                && !periods.nameOn(sheetId, old).equals(periods.nameOn(sheetId, date))) {
426	            claim.setNumber(nextNumber(sheetId, date));
427	        }
428	        claim.setDate(date);
429	        if (!claim.isCorrection()) {
430	            claim.setRoundingDate(date);
431	        }
432	        Claim saved = claims.saveAndFlush(claim);
433	        audit.recordOnCommit(record("CLAIM_REDATED", user, person, saved) + numberOf(saved.getNumber())
434	                + " old=" + old + " new=" + date);
435	        rollup.recordChanges(sheetId, user, before);
436	        return saved;
437	    }
