439	    /**
440	     * Split an amount (more than 0.00 and less than its own) off an OPEN claim not deferred. The claim keeps the rest
441	     * and loses any figure a statement bound it to; a new OPEN claim of the same person with the amount split off, the
442	     * same date and note, the next number, opened by the user, due by its date plus the terms in force on that date,
443	     * names the claim's number as the one it was split from. Refused for any other status, a closed period, or a user
444	     * whose role may not open a claim.
445	     */
446	    @Transactional
447	    public Claim split(String sheetId, String user, Long id, BigDecimal amount) {
448	        Claim claim = claims.findForUpdate(id, sheetId)
449	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
450	        if (!roles.may(sheetId, user, "open")) {
451	            throw new ClaimActionForbiddenException(id, user, "open");
452	        }
453	        if (claim.getStatus() != ClaimStatus.OPEN) {
454	            throw new ClaimSplitException(id, "it is " + claim.getStatus() + ", only an OPEN claim can be split");
455	        }
456	        if (claim.isDeferredOn(sheets.today(sheetId))) {
457	            throw new ClaimSplitException(id, "it is deferred until " + claim.getDeferredUntil());
458	        }
459	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
460	            throw new ClaimSplitException(id, "the amount split off must be more than 0.00 and less than "
461	                    + claim.getAmount().toPlainString());
462	        }
463	        periods.requireOpen(sheetId, claim.getDate());
464	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
465	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
466	        RollupService.Snapshot before = rollup.snapshot(sheetId);
467	        claim.setAmount(claim.getAmount().subtract(amount));
468	        claim.setStated(false, null);
469	        Claim kept = claims.saveAndFlush(claim);
470	        Claim part = new Claim(sheetId, kept.getPersonId(), amount, kept.getDate(), kept.getNote());
471	        part.setRoundingDate(kept.getRoundingDate());
472	        part.setDueBy(kept.getDate().plusDays(termsFor(sheetId, person, kept.getDate())));
473	        part.setListed(sheets.nextListed(sheetId));
474	        part.setStatus(ClaimStatus.OPEN);
475	        String number = nextNumber(sheetId, kept.getDate());
476	        part.setNumber(number);
477	        part.setOpenedBy(user);
478	        part.setSplitFrom(kept.getNumber());
479	        Claim saved = claims.saveAndFlush(part);
480	        log(sheetId, user, person, saved);
481	        audit.recordOnCommit(record("CLAIM_SPLIT", user, person, kept) + numberOf(kept.getNumber())
482	                + " into=" + number);
483	        audit.recordOnCommit(record("CLAIM_OPENED", user, person, saved) + numberOf(number));
484	        rollup.recordChanges(sheetId, user, before);
485	        return saved;
486	    }
