508	    /**
509	     * A claim whose due (as the clerk limit weighs it) is above the proof threshold in force on its date cannot be
510	     * settled or approved while it has no proof; refused then. A due of n/a is within any threshold.
511	     */
512	    private void requireProof(String sheetId, Person person, Claim claim) {
513	        BigDecimal threshold = settings.get(sheetId).proofThresholdOn(claim.getDate());
514	        if (threshold == null || claim.getProofs() > 0) {
515	            return;
516	        }
517	        BigDecimal due = liveDue(sheetId, claim, figureOf(sheetId, person, claim));
518	        if (due != null && due.compareTo(threshold) > 0) {
519	            throw new ClaimProofException(claim.getId(), "its due " + due.toPlainString()
520	                    + " is above the proof threshold " + threshold.toPlainString() + " and it has no proof");
521	        }
522	    }
