525	     * A claim whose due is above the note threshold in force on its date cannot be opened while its note is empty;
526	     * refused then. A due of n/a is within any threshold.
527	     */
528	    private void requireNote(String sheetId, Person person, Claim claim) {
529	        BigDecimal threshold = settings.get(sheetId).noteThresholdOn(claim.getDate());
530	        if (threshold == null || !noteOf(claim.getNote()).isEmpty()) {
531	            return;
532	        }
533	        BigDecimal due = liveDue(sheetId, claim, figureOf(sheetId, person, claim));
534	        if (due != null && due.compareTo(threshold) > 0) {
535	            throw new ClaimNoteException(claim.getId(), "its due " + due.toPlainString()
536	                    + " is above the note threshold " + threshold.toPlainString() + " and its note is empty");
537	        }
538	    }
