540	    /**
541	     * Only a steward voids a SETTLED claim, and only within the days allowed after its settlement (the date of the last
542	     * SETTLED line of its status log) by the sheet's today; refused otherwise.
543	     */
544	    private void requireSettledVoidable(String sheetId, String user, Claim claim) {
545	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
546	            throw new ClaimActionForbiddenException(claim.getId(), user, "void a settled claim");
547	        }
548	        LocalDate settledOn = logOf(claim).stream()
549	                .filter(l -> l.getStatus() == ClaimStatus.SETTLED)
550	                .map(ClaimLog::getDate)
551	                .reduce((first, last) -> last)
552	                .orElse(null);
553	        LocalDate today = sheets.today(sheetId);
554	        if (settledOn == null || today.isAfter(settledOn.plusDays(SETTLED_VOID_DAYS))) {
555	            throw new ClaimVoidException(claim.getId(), "a settled claim can only be voided within "
556	                    + SETTLED_VOID_DAYS + " days of its settlement on " + settledOn);
557	        }
558	    }
